from selenium.webdriver.common.by import By
from taf.selenium.sbts.common.common import LocalBasicPage


class GeneralBtsSiteSettings(LocalBasicPage):
    """
    Implementation class for specific tab page, has to include tow class variable
    "_methods_list" and "_tab_name"
    """
    _tab_name = 'General BTS/Site Settings'
    _BTS_NAME_XPATH = '//label[contains(text(), "BTS name")]/ancestor::wizard-parameter-input//input'

    def __init__(self, driver):
        super(GeneralBtsSiteSettings, self).__init__(driver)

    def set_bts_name(self, name, timeout=60):
        if name is not None:
            self.insert_text_to_enable_element((By.XPATH, self._BTS_NAME_XPATH), name, timeout)
